  height: 28px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 700;
  flex-shrink: 0;
}
.pipe-title { font-weight: 600; font-size: 14px; margin-bottom: 4px; }

/* —— AI reports —— */
.tpl-list { display: grid; gap: 12px; }
.tpl-item {
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #f8fafc;
}
.tpl-name {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-weight: 600;
  font-size: 13px;
  margin-bottom: 4px;
}
