  color: #e2e8f0;
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.65;
  white-space: pre-wrap;
  font-family: ui-monospace, Consolas, monospace;
  overflow: auto;
}

@media (max-width: 900px) {
