  text-align: center;
  color: var(--muted);
  font-size: 14px;
}

/* —— Dashboard —— */
.dash-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}
.bar-list { display: grid; gap: 12px; }
.bar-row { display: grid; gap: 6px; }
.bar-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text);
}
.bar-track {
  height: 8px;
  background: #f1f5f9;
  border-radius: 999px;
  overflow: hidden;
}
.bar-fill {
  height: 100%;
  border-radius: 999px;
  min-width: 0;
  transition: width 0.25s ease;
}
.bar-fill.platform { background: linear-gradient(90deg, #0f766e, #2dd4bf); }
.platform-tag {
  text-transform: capitalize;
  font-weight: 600;
}
.chip {
  display: inline-flex;
  align-items: center;
  padding: 6px 10px;
  border-radius: 999px;
  background: #f0fdfa;
  border: 1px solid #99f6e4;
  color: var(--primary);
  font-size: 12px;
  font-weight: 600;
  text-transform: capitalize;
}

@media (max-width: 900px) {
  .dash-grid { grid-template-columns: 1fr; }
}

/* —— Plugin center —— */
.plugin-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
.plugin-card { display: flex; flex-direction: column; gap: 10px; }
.plugin-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}
.plugin-name { font-size: 15px; font-weight: 700; }
.plugin-desc {
  margin: 0;
  font-size: 13px;
  color: var(--muted);
  line-height: 1.55;
  flex: 1;
}
.badge-status {
  flex-shrink: 0;
  border-radius: 999px;
  padding: 3px 10px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.badge-status.ready { background: #d1fae5; color: var(--ok); }
.badge-status.building { background: #ffedd5; color: var(--warn); }
.badge-status.pending { background: #dbeafe; color: #1d4ed8; }
.badge-status.planned { background: #e5e7eb; color: #4b5563; }

/* —— Shipping —— */
.pipeline {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.pipe-step {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #f8fafc;
}
.pipe-num {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 700;
  flex-shrink: 0;
}
.pipe-title { font-weight: 600; font-size: 14px; margin-bottom: 4px; }

/* —— AI reports —— */
.tpl-list { display: grid; gap: 12px; }
.tpl-item {
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #f8fafc;
}
.tpl-name {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-weight: 600;
  font-size: 13px;
  margin-bottom: 4px;
}
.ai-preview {
  margin: 0;
  padding: 14px 16px;
  background: #0f172a;
  color: #e2e8f0;
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.65;
  white-space: pre-wrap;
  font-family: ui-monospace, Consolas, monospace;
  overflow: auto;
}

@media (max-width: 900px) {
  .plugin-grid { grid-template-columns: 1fr; }
  .pipeline { grid-template-columns: 1fr 1fr; }
  .platform-entry-grid,
  .boss-entry-grid { grid-template-columns: 1fr; }
  .nav-children { margin-left: 0; border-left: none; padding-left: 0; }
}

@media (max-width: 560px) {
  .pipeline { grid-template-columns: 1fr; }
}

.hint-list {
  margin: 0;
  padding-left: 18px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
}

.drawer-mask {
  position: fixed; inset: 0; background: rgba(15, 23, 42, 0.35);
  display: grid; place-items: end center; padding: 24px;
  z-index: 50;
}
.drawer {
  width: min(520px, 100%); background: #fff; border-radius: 16px;
  padding: 18px; box-shadow: var(--shadow);
}

@media (max-width: 900px) {
  .grid-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .app-layout { flex-direction: column; }
  .sidebar {
    width: 100%;
    flex: none;
    height: auto;
    position: relative;
  }
  .sidebar-nav {
    flex-direction: row;
    flex-wrap: wrap;
    overflow-x: auto;
  }
  .nav-item { width: auto; }
  .sidebar-foot { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
  .sidebar-foot .logout { width: auto; margin-top: 0; }
