:root {
  color-scheme: light;
  --bg: #f0f4f5;
  --sidebar: #0f3d3a;
  --sidebar-hover: rgba(255, 255, 255, 0.08);
  --sidebar-active: rgba(45, 212, 191, 0.18);
  --sidebar-text: #d1fae5;
  --sidebar-muted: #99bdb8;
  --card: #ffffff;
  --text: #1f2937;
  --muted: #6b7280;
  --line: #e5e7eb;
  --primary: #0f766e;
  --primary-hover: #0d9488;
  --danger: #b91c1c;
  --warn: #b45309;
  --ok: #047857;
  --shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
  --sidebar-w: 236px;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
}

* { box-sizing: border-box; }
html, body, #app { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
}
button, input, select, textarea { font: inherit; }
a { color: var(--primary); }

/* —— Login —— */
.login-wrap {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: linear-gradient(160deg, #ecfeff 0%, var(--bg) 55%);
}
.login-card { width: min(420px, 100%); }
.login-card h1 { margin: 0 0 6px; font-size: 22px; }
.login-card .sub { color: var(--muted); margin-bottom: 18px; font-size: 13px; }

/* —— Shell: left nav + right content —— */
.app-layout {
  display: flex;
  min-height: 100vh;
  height: 100%;
}

.sidebar {
  width: var(--sidebar-w);
  flex: 0 0 var(--sidebar-w);
  background: linear-gradient(180deg, #0f3d3a 0%, #0a2e2b 100%);
  color: var(--sidebar-text);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  position: sticky;
  top: 0;
  align-self: flex-start;
  height: 100vh;
}

.sidebar-brand {
  padding: 22px 18px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.sidebar-brand .logo {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #fff;
}
.sidebar-brand .tag {
  margin-top: 6px;
  font-size: 12px;
  color: var(--sidebar-muted);
}

.sidebar-nav {
  flex: 1;
  padding: 10px 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow-y: auto;
}

.nav-section-label {
  margin: 12px 10px 6px;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sidebar-muted);
  font-weight: 600;
}
.nav-section-label:first-child { margin-top: 4px; }

.nav-group { display: flex; flex-direction: column; gap: 2px; }

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  border: none;
  background: transparent;
  color: var(--sidebar-text);
  text-align: left;
  padding: 10px 12px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 13.5px;
  transition: background 0.15s ease;
}
.nav-item:hover { background: var(--sidebar-hover); }
.nav-item.active {
  background: var(--sidebar-active);
  color: #fff;
  font-weight: 600;
  box-shadow: inset 3px 0 0 #2dd4bf;
}
.nav-item .icon {
  width: 20px;
  text-align: center;
  opacity: 0.9;
  font-size: 15px;
}
.nav-item .label { flex: 1; min-width: 0; }
.nav-item .chevron {
  font-size: 11px;
  color: var(--sidebar-muted);
  width: 14px;
  text-align: center;
}
.nav-item.nav-group-head.open {
  background: rgba(255, 255, 255, 0.06);
}
.nav-item.nav-group-head.active:not(.child) {
  box-shadow: none;
}
.platform-icon {
  width: 20px;
  height: 20px;
  border-radius: 6px;
  background: rgba(45, 212, 191, 0.2);
  color: #5eead4;
  font-size: 11px;
  font-weight: 800;
  display: inline-grid;
  place-items: center;
  line-height: 1;
}
.nav-children {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 0 6px 8px;
  margin-left: 12px;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
}
.nav-item.child {
  padding: 8px 12px;
  font-size: 13px;
  color: #b7d4cf;
}
.nav-item.child.active {
  color: #fff;
}

